def valid_list(x):
    n = len(x)
    if n > 4:
        return False
    for i in range(n):
        v = x[i]
        if v < -9 or v > 9:
            return False
    if n > 1:
        for i in range(n - 1):
            if x[i] > x[i + 1]:
                return False
    return True

def pre(a, b):
    if not valid_list(a):
        return False
    if not valid_list(b):
        return False
    return True

def post(a, b, result):
    combined = []
    for x in a:
        combined.append(x)
    for x in b:
        combined.append(x)
    expected = sorted(combined)
    return result == expected
